export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-31\",\"workId\":\"han-fei-zi\",\"order\":31,\"title\":\"內儲說下\",\"difficulty\":4,\"estimatedMinutes\":18,\"passageIds\":[\"han-fei-zi_ch-31_p-1\",\"han-fei-zi_ch-31_p-2\",\"han-fei-zi_ch-31_p-3\",\"han-fei-zi_ch-31_p-4\",\"han-fei-zi_ch-31_p-5\",\"han-fei-zi_ch-31_p-6\",\"han-fei-zi_ch-31_p-7\",\"han-fei-zi_ch-31_p-8\",\"han-fei-zi_ch-31_p-9\",\"han-fei-zi_ch-31_p-10\",\"han-fei-zi_ch-31_p-11\",\"han-fei-zi_ch-31_p-12\",\"han-fei-zi_ch-31_p-13\",\"han-fei-zi_ch-31_p-14\",\"han-fei-zi_ch-31_p-15\",\"han-fei-zi_ch-31_p-16\",\"han-fei-zi_ch-31_p-17\",\"han-fei-zi_ch-31_p-18\",\"han-fei-zi_ch-31_p-19\",\"han-fei-zi_ch-31_p-20\",\"han-fei-zi_ch-31_p-21\",\"han-fei-zi_ch-31_p-22\",\"han-fei-zi_ch-31_p-23\",\"han-fei-zi_ch-31_p-24\",\"han-fei-zi_ch-31_p-25\",\"han-fei-zi_ch-31_p-26\",\"han-fei-zi_ch-31_p-27\",\"han-fei-zi_ch-31_p-28\",\"han-fei-zi_ch-31_p-29\",\"han-fei-zi_ch-31_p-30\",\"han-fei-zi_ch-31_p-31\",\"han-fei-zi_ch-31_p-32\",\"han-fei-zi_ch-31_p-33\",\"han-fei-zi_ch-31_p-34\",\"han-fei-zi_ch-31_p-35\",\"han-fei-zi_ch-31_p-36\",\"han-fei-zi_ch-31_p-37\",\"han-fei-zi_ch-31_p-38\",\"han-fei-zi_ch-31_p-39\",\"han-fei-zi_ch-31_p-40\",\"han-fei-zi_ch-31_p-41\",\"han-fei-zi_ch-31_p-42\",\"han-fei-zi_ch-31_p-43\",\"han-fei-zi_ch-31_p-44\",\"han-fei-zi_ch-31_p-45\",\"han-fei-zi_ch-31_p-46\",\"han-fei-zi_ch-31_p-47\",\"han-fei-zi_ch-31_p-48\",\"han-fei-zi_ch-31_p-49\",\"han-fei-zi_ch-31_p-50\",\"han-fei-zi_ch-31_p-51\",\"han-fei-zi_ch-31_p-52\",\"han-fei-zi_ch-31_p-53\",\"han-fei-zi_ch-31_p-54\",\"han-fei-zi_ch-31_p-55\",\"han-fei-zi_ch-31_p-56\",\"han-fei-zi_ch-31_p-57\",\"han-fei-zi_ch-31_p-58\",\"han-fei-zi_ch-31_p-59\",\"han-fei-zi_ch-31_p-60\",\"han-fei-zi_ch-31_p-61\",\"han-fei-zi_ch-31_p-62\",\"han-fei-zi_ch-31_p-63\",\"han-fei-zi_ch-31_p-64\",\"han-fei-zi_ch-31_p-65\",\"han-fei-zi_ch-31_p-66\",\"han-fei-zi_ch-31_p-67\",\"han-fei-zi_ch-31_p-68\",\"han-fei-zi_ch-31_p-69\",\"han-fei-zi_ch-31_p-70\",\"han-fei-zi_ch-31_p-71\",\"han-fei-zi_ch-31_p-72\",\"han-fei-zi_ch-31_p-73\",\"han-fei-zi_ch-31_p-74\",\"han-fei-zi_ch-31_p-75\",\"han-fei-zi_ch-31_p-76\",\"han-fei-zi_ch-31_p-77\",\"han-fei-zi_ch-31_p-78\",\"han-fei-zi_ch-31_p-79\",\"han-fei-zi_ch-31_p-80\",\"han-fei-zi_ch-31_p-81\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-31_p-1\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":1,\"canonicalText\":\"六微：一曰、權借在下，二曰、利異外借，三曰、託於似類，四曰、利害有反，五曰、參疑內爭，六曰、敵國廢置。此六者，主之所察也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-1_s-1\",\"han-fei-zi_ch-31_p-1_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"六微：一說道：、權借在下，二說道：、利異外借，三說道：、託於似類，四說道：、利害有反，五說道：、參疑內爭，六說道：、敵國廢置。此六的人或事物，主的所察啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「六微：一曰、權借在下，二曰、利異外借，三曰、託於似類，四曰、利害有反，五曰、參疑內爭，六曰、敵國廢置」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「六微：一曰、權借在下，二曰、利異外借，三曰、託於似類……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-2\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":2,\"canonicalText\":\"權勢不可以借人，上失其一，臣以為百。故臣得借則力多，力多則內外為用，內外為用則人主壅。其說在老聃之言失魚也。是以人主久語，而左右鬻懷刷。其患在胥僮之諫厲公，與州侯之一言，而燕人浴矢也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-2_s-1\",\"han-fei-zi_ch-31_p-2_s-2\",\"han-fei-zi_ch-31_p-2_s-3\",\"han-fei-zi_ch-31_p-2_s-4\",\"han-fei-zi_ch-31_p-2_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"權至高權力威勢不可以借人，上失他的一，臣下僚屬以為百。所以臣下僚屬得借則力多，力多則內外為用，內外為用則人主壅。他的說在老聃的言失魚啊。是以人主久語，而且左右鬻懷刷。他的患在胥僮的諫厲公，與州侯的一言，而且燕人浴矢啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「權勢不可以借人，上失其一，臣以為百」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「權勢不可以借人，上失其一，臣以為百。故臣得借則力多，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-3\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":3,\"canonicalText\":\"權借一\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-3_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"權借一。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「權借一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「權借一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-4\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":4,\"canonicalText\":\"君臣之利異，故人臣莫忠，故臣利立而主利滅。是以姦臣者，召敵兵以內除，舉外事以眩主，苟成其私利，不顧國患。其說在衛人之夫妻禱祝也。故戴歇議子弟，而三桓攻昭公；公叔內齊軍，而翟黃召韓兵；太宰嚭說大夫種，大成牛教申不害；司馬喜告趙王，呂倉規秦、楚；宋石遺衛君書，白圭教暴譴。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-4_s-1\",\"han-fei-zi_ch-31_p-4_s-2\",\"han-fei-zi_ch-31_p-4_s-3\",\"han-fei-zi_ch-31_p-4_s-4\",\"han-fei-zi_ch-31_p-4_s-5\",\"han-fei-zi_ch-31_p-4_s-6\",\"han-fei-zi_ch-31_p-4_s-7\",\"han-fei-zi_ch-31_p-4_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"君主統治者臣下僚屬的利異，所以人臣下僚屬莫忠，所以臣下僚屬利立而且主利滅。是以姦臣下僚屬的人或事物，召敵兵以內除，舉外事以眩主，苟成他的私利，不顧國患。他的說在衛人的夫妻禱祝啊。所以戴歇議子弟，而且三桓攻昭公；公叔內齊軍，而且翟黃召韓兵；太宰嚭說大夫種，大成牛教申不害；司馬喜告趙王，呂倉規秦、楚；宋石遺衛君主統治者書，白圭教暴譴。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「君臣之利異，故人臣莫忠，故臣利立而主利滅」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「君臣之利異，故人臣莫忠，故臣利立而主利滅。是以姦臣者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-5\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":5,\"canonicalText\":\"利異二\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-5_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"利異二。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「利異二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「利異二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-6\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":6,\"canonicalText\":\"似類之事，人主之所以失誅，而大臣之所以成私也。是以門人捐水而夷射誅，濟陽自矯而二人罪，司馬喜殺爰騫而季辛誅，鄭袖言惡臭而新人劓，費無忌教郤宛而令尹誅，陳需殺張壽而犀首走。故燒芻廥而中山罪，殺老儒而濟陽賞也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-6_s-1\",\"han-fei-zi_ch-31_p-6_s-2\",\"han-fei-zi_ch-31_p-6_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"似類的事，人主的所以失誅，而且大臣下僚屬的所以成私啊。是以門人捐水而且夷射誅，濟陽自矯而且二人罪，司馬喜殺爰騫而且季辛誅，鄭袖言惡臭而且新人劓，費無忌教郤宛而且令尹誅，陳需殺張壽而且犀首走。所以燒芻廥而且中山罪，殺老儒而且濟陽賞賜恩惠啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「似類之事，人主之所以失誅，而大臣之所以成私也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「似類之事，人主之所以失誅，而大臣之所以成私也。是以門……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-7\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":7,\"canonicalText\":\"似類三\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-7_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"似類三。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「似類三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「似類三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-8\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":8,\"canonicalText\":\"事起而有所利，其屍主之；有所害，必反察之。是以明主之論也，國害則省其利者，臣害則察其反者。其說在楚兵至而陳需相，黍種貴而廩吏覆。是以昭奚恤執販茅，而不僖侯譙其次；文公髮繞炙，而穰侯請立帝。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-8_s-1\",\"han-fei-zi_ch-31_p-8_s-2\",\"han-fei-zi_ch-31_p-8_s-3\",\"han-fei-zi_ch-31_p-8_s-4\",\"han-fei-zi_ch-31_p-8_s-5\",\"han-fei-zi_ch-31_p-8_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"事起而且有所利，他的屍主的；有所害，必反察的。是以明主的論啊，國害則省他的利的人或事物，臣下僚屬害則察他的反的人或事物。他的說在楚兵至而且陳需相，黍種貴而且廩吏覆。是以昭奚恤執販茅，而且不僖侯譙他的次；文公髮繞炙，而且穰侯請立帝。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「事起而有所利，其屍主之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「事起而有所利，其屍主之；有所害，必反察之。是以明主之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-9\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":9,\"canonicalText\":\"有反四\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-9_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有反四。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「有反四」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「有反四」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-10\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":10,\"canonicalText\":\"參疑之勢，亂之所由生也，故明主慎之。是以晉驪姬殺太子申生，而鄭夫人用毒藥，郤州籲殺其君完，公子根取東周，王子職甚有寵，而商臣果作亂，嚴遂、韓廆爭而哀侯果遇賊，田常、闞止、戴驩、皇喜敵而宋君、簡公殺。其說在狐突之稱二好，與鄭昭之對未生也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-10_s-1\",\"han-fei-zi_ch-31_p-10_s-2\",\"han-fei-zi_ch-31_p-10_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"參疑的至高權力威勢，亂的所由生啊，所以明主慎的。是以晉驪姬殺太子申生，而且鄭夫人用毒藥，郤州籲殺他的君主統治者完，公子根取東周，王子職甚有寵，而且商臣下僚屬果作亂，嚴遂、韓廆爭而且哀侯果遇賊，田常、闞止、戴驩、皇喜敵而且宋君主統治者、簡公殺。他的說在狐突的稱二好，與鄭昭的對未生啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「參疑之勢，亂之所由生也，故明主慎之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「參疑之勢，亂之所由生也，故明主慎之。是以晉驪姬殺太子……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-11\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":11,\"canonicalText\":\"參疑五\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-11_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"參疑五。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「參疑五」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「參疑五」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-12\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":12,\"canonicalText\":\"敵之所務在淫察而就靡，人主不察則敵廢置矣。故文王資費仲，而秦王患楚使，黎且去仲尼，而乾象沮甘茂。是以子胥宣言而子常用，內美人而虞、虢亡，佯遺書而萇宏死，用雞猳而鄶桀盡。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-12_s-1\",\"han-fei-zi_ch-31_p-12_s-2\",\"han-fei-zi_ch-31_p-12_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"敵的所務在淫察而且就靡，人主不察則敵廢置矣。所以文王資費仲，而且秦王患楚使，黎且去仲尼，而且乾象沮甘茂。是以子胥宣言而且子常用，內美人而且虞、虢亡，佯遺書而且萇宏死，用雞猳而且鄶桀盡。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「敵之所務在淫察而就靡，人主不察則敵廢置矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「敵之所務在淫察而就靡，人主不察則敵廢置矣。故文王資費……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-13\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":13,\"canonicalText\":\"廢置六\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-13_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"廢置六。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「廢置六」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「廢置六」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-14\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":14,\"canonicalText\":\"參疑廢置之事，明主絕之於內而施之於外。資其輕者，輔其弱者，此謂廟攻。參伍既用於內，觀聽又行於外，則敵偽得。其說在秦侏儒之告惠文君也。故襄疵言襲鄴，而嗣公賜令蓆。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-14_s-1\",\"han-fei-zi_ch-31_p-14_s-2\",\"han-fei-zi_ch-31_p-14_s-3\",\"han-fei-zi_ch-31_p-14_s-4\",\"han-fei-zi_ch-31_p-14_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"參疑廢置的事，明主絕的於內而且施的於外。資他的輕的人或事物，輔他的弱的人或事物，此謂廟攻。參伍既用於內，觀聽又行於外，則敵偽得。他的說在秦侏儒的告惠文君主統治者啊。所以襄疵言襲鄴，而且嗣公賜令蓆。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「參疑廢置之事，明主絕之於內而施之於外」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「參疑廢置之事，明主絕之於內而施之於外。資其輕者，輔其……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-15\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":15,\"canonicalText\":\"廟攻\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-15_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"廟攻。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「廟攻」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「廟攻」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-16\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":16,\"canonicalText\":\"右經\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-16_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"右經。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「右經」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「右經」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-17\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":17,\"canonicalText\":\"說一\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-17_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說一。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-18\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":18,\"canonicalText\":\"勢重者，人主之淵也；臣者，勢重之魚也。魚失於淵而不可復得也，人主失其勢重於臣而不可復收也。古之人難正言，故託之於魚。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-18_s-1\",\"han-fei-zi_ch-31_p-18_s-2\",\"han-fei-zi_ch-31_p-18_s-3\",\"han-fei-zi_ch-31_p-18_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"至高權力威勢重的人或事物，人主的淵啊；臣下僚屬的人或事物，至高權力威勢重的魚啊。魚失於淵而且不可復得啊，人主失他的至高權力威勢重於臣下僚屬而且不可復收啊。古的人難正言，所以託的於魚。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「勢重者，人主之淵也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「勢重者，人主之淵也；臣者，勢重之魚也。魚失於淵而不可……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-19\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":19,\"canonicalText\":\"賞罰者，利器也。君操之以制臣，臣得之以擁主。故君先見所賞則臣鬻之以為德，君先見所罰則臣鬻之以為威。故曰：「國之利器不可以示人。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-19_s-1\",\"han-fei-zi_ch-31_p-19_s-2\",\"han-fei-zi_ch-31_p-19_s-3\",\"han-fei-zi_ch-31_p-19_s-4\",\"han-fei-zi_ch-31_p-19_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"賞賜恩惠刑罰制裁的人或事物，利器啊。君主統治者操的以制臣下僚屬，臣下僚屬得的以擁主。所以君主統治者先見所賞賜恩惠則臣下僚屬鬻的以為德，君主統治者先見所刑罰制裁則臣下僚屬鬻的以為威。因此韓絕不是子評論說道：國的利器不可以示人。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「賞罰者，利器也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「賞罰者，利器也。君操之以制臣，臣得之以擁主。故君先見……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-20\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":20,\"canonicalText\":\"靖郭君相齊，與故人久語則故人富，懷左右刷則左右重。久語懷刷，小資也，猶以成富，況於吏勢乎？\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-20_s-1\",\"han-fei-zi_ch-31_p-20_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"靖郭君主統治者相齊，與所以人久語則所以人富，懷左右刷則左右重。久語懷刷，小資啊，猶以成富，況於吏至高權力威勢乎？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「靖郭君相齊，與故人久語則故人富，懷左右刷則左右重」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「靖郭君相齊，與故人久語則故人富，懷左右刷則左右重。久……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-21\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":21,\"canonicalText\":\"晉厲公之時，六卿貴。胥僮長魚矯諫曰：「大臣貴重，敵主爭事，外市樹黨，下亂國法，上以劫主，而國不危者，未嘗有也。」公曰：「善。」乃誅三卿。胥僮長魚矯又諫曰：「夫同罪之人偏誅而不盡，是懷怨而借之閒也。」公曰：「吾一朝而夷三卿，予不忍盡也。」長魚矯對曰：「公不忍之，彼將忍公。」公不聽，居三月，諸卿作難，遂殺厲公而分其地。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-21_s-1\",\"han-fei-zi_ch-31_p-21_s-2\",\"han-fei-zi_ch-31_p-21_s-3\",\"han-fei-zi_ch-31_p-21_s-4\",\"han-fei-zi_ch-31_p-21_s-5\",\"han-fei-zi_ch-31_p-21_s-6\",\"han-fei-zi_ch-31_p-21_s-7\",\"han-fei-zi_ch-31_p-21_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"晉厲公的時，六卿貴。胥僮長魚矯諫說道：大臣下僚屬貴重，敵主爭事，外市樹黨，下亂國國家法度法規，上以劫主，而且國不危的人或事物，未嘗有啊。公說道：善。乃誅三卿。胥僮長魚矯又諫說道：夫同罪的人偏誅而且不盡，是懷怨而且借的閒啊。公說道：吾一朝而且夷三卿，予不忍盡啊。長魚矯對說道：公不忍的，彼將忍公。公不聽，居三月，諸卿作難，遂殺厲公而且分他的地。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「晉厲公之時，六卿貴」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「晉厲公之時，六卿貴。胥僮長魚矯諫曰：「大臣貴重，敵主……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-22\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":22,\"canonicalText\":\"州侯相荊，貴而主斷，荊王疑之，因問左右，左右對曰「無有」，如出一口也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-22_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"州侯相荊，貴而且主斷，荊王疑的，因問左右，左右對說道：無有，如出一口啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「州侯相荊，貴而主斷，荊王疑之，因問左右，左右對曰「無有」，如出一口也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「州侯相荊，貴而主斷，荊王疑之，因問左右，左右對曰「無……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-23\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":23,\"canonicalText\":\"燕人無惑，故浴狗矢。燕人、其妻有私通於士，其夫早自外而來，士適出，夫曰：「何客也？」其妻曰：「無客。」問左右，左右言無有，如出一口。其妻曰：「公惑易也。」因浴之以狗矢。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-23_s-1\",\"han-fei-zi_ch-31_p-23_s-2\",\"han-fei-zi_ch-31_p-23_s-3\",\"han-fei-zi_ch-31_p-23_s-4\",\"han-fei-zi_ch-31_p-23_s-5\",\"han-fei-zi_ch-31_p-23_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"燕人無惑，所以浴狗矢。燕人、他的妻有私通於士，他的夫早自外而且來，士適出，夫說道：何客啊？他的妻說道：無客。問左右，左右言無有，如出一口。他的妻說道：公惑易啊。因浴的以狗矢。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 23 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「燕人無惑，故浴狗矢」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「燕人無惑，故浴狗矢。燕人、其妻有私通於士，其夫早自外……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-24\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":24,\"canonicalText\":\"一曰。燕人李季好遠出，其妻私有通於士，季突至，士在內中，妻患之，其室婦曰：「令公子裸而解髮直出門，吾屬佯不見也。」於是公子從其計，疾走出門，季曰：「是何人也？」家室皆曰：「無有。」季曰：「吾見鬼乎？」婦人曰：「然。」「為之奈何？」曰：「取五姓之矢浴之。」季曰：「諾。」乃浴以矢。一曰浴以蘭湯。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-24_s-1\",\"han-fei-zi_ch-31_p-24_s-2\",\"han-fei-zi_ch-31_p-24_s-3\",\"han-fei-zi_ch-31_p-24_s-4\",\"han-fei-zi_ch-31_p-24_s-5\",\"han-fei-zi_ch-31_p-24_s-6\",\"han-fei-zi_ch-31_p-24_s-7\",\"han-fei-zi_ch-31_p-24_s-8\",\"han-fei-zi_ch-31_p-24_s-9\",\"han-fei-zi_ch-31_p-24_s-10\",\"han-fei-zi_ch-31_p-24_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。燕人李季好遠出，他的妻私有通於士，季突至，士在內中，妻患的，他的室婦說道：令公子裸而且解髮直出門，吾屬佯不見啊。於是公子從他的計，疾走出門，季說道：是何人啊？家室皆說道：無有。季說道：吾見鬼乎？婦人說道：然。為的奈何？說道：取五姓的矢浴的。季說道：諾。乃浴以矢。一說道：浴以蘭湯。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 24 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。燕人李季好遠出，其妻私有通於士，季突至，士在內……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-25\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":25,\"canonicalText\":\"說二\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-25_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說二。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 25 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-26\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":26,\"canonicalText\":\"衛人有夫妻禱者，而祝曰：「使我無故，得百束布。」其夫曰：「何少也？」對曰：「益是，子將以買妾。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-26_s-1\",\"han-fei-zi_ch-31_p-26_s-2\",\"han-fei-zi_ch-31_p-26_s-3\",\"han-fei-zi_ch-31_p-26_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛人有夫妻禱的人或事物，而且祝說道：使我無所以，得百束布。他的夫說道：何少啊？對說道：益是，子將以買妾。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 26 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛人有夫妻禱者，而祝曰：「使我無故，得百束布」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛人有夫妻禱者，而祝曰：「使我無故，得百束布。」其夫……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-27\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":27,\"canonicalText\":\"荊王欲宦諸公子於四鄰，戴歇曰：「不可。」「宦公子於四鄰，四鄰必重之」。曰：「子出者重，重則必為所重之國黨，則是教子於外市也，不便。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-27_s-1\",\"han-fei-zi_ch-31_p-27_s-2\",\"han-fei-zi_ch-31_p-27_s-3\",\"han-fei-zi_ch-31_p-27_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"荊王欲宦諸公子於四鄰，戴歇說道：不可。宦公子於四鄰，四鄰必重的。說道：子出的人或事物重，重則必為所重的國黨，則是教子於外市啊，不便。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 27 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「荊王欲宦諸公子於四鄰，戴歇曰：「不可」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「荊王欲宦諸公子於四鄰，戴歇曰：「不可。」「宦公子於四……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-28\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":28,\"canonicalText\":\"魯孟孫、叔孫、季孫相戮力劫昭公，遂奪其國而擅其制。魯三桓公偪，昭公攻季孫氏，而孟孫氏、叔孫氏相與謀曰：「救之乎？」叔孫氏之御者曰：「我，家臣也，安知公家？凡有季孫與無季孫於我孰利？」皆曰：「無季孫必無叔孫。」「然則救之。」於是撞西北隅而入，孟孫見叔孫之旗入，亦救之，三桓為一，昭公不勝，逐之死於乾侯。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-28_s-1\",\"han-fei-zi_ch-31_p-28_s-2\",\"han-fei-zi_ch-31_p-28_s-3\",\"han-fei-zi_ch-31_p-28_s-4\",\"han-fei-zi_ch-31_p-28_s-5\",\"han-fei-zi_ch-31_p-28_s-6\",\"han-fei-zi_ch-31_p-28_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魯孟孫、叔孫、季孫相戮力劫昭公，遂奪他的國而且擅他的制。魯三桓公偪，昭公攻季孫氏，而且孟孫氏、叔孫氏相與謀說道：救的乎？叔孫氏的御的人或事物說道：我，家臣下僚屬啊，安知公家？凡有季孫與無季孫於我孰利？皆說道：無季孫必無叔孫。然則救的。於是撞西北隅而且入，孟孫見叔孫的旗入，亦救的，三桓為一，昭公不勝，逐的死於乾侯。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 28 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魯孟孫、叔孫、季孫相戮力劫昭公，遂奪其國而擅其制」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魯孟孫、叔孫、季孫相戮力劫昭公，遂奪其國而擅其制。魯……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-29\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":29,\"canonicalText\":\"公叔相韓而有攻齊，公仲甚重於王，公叔恐王之相公仲也，使齊、韓約而攻魏，公叔因內齊軍於鄭，以劫其君，以固其位，而信兩國之約。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-29_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公叔相韓而且有攻齊，公仲甚重於王，公叔恐王的相公仲啊，使齊、韓約而且攻魏，公叔因內齊軍於鄭，以劫他的君主統治者，以固他的位，而且信兩國的約。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 29 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「公叔相韓而有攻齊，公仲甚重於王，公叔恐王之相公仲也，使齊、韓約而攻魏，公叔因內齊軍於鄭，以劫其君，以固其位，而信兩國之約」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「公叔相韓而有攻齊，公仲甚重於王，公叔恐王之相公仲也，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-30\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":30,\"canonicalText\":\"翟璜，魏王之臣也，而善於韓，乃召韓兵令之攻魏，因請為魏王搆之以自重也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-30_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"翟璜，魏王的臣下僚屬啊，而且善於韓，乃召韓兵令的攻魏，因請為魏王搆的以自重啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 30 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「翟璜，魏王之臣也，而善於韓，乃召韓兵令之攻魏，因請為魏王搆之以自重也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「翟璜，魏王之臣也，而善於韓，乃召韓兵令之攻魏，因請為……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-31\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":31,\"canonicalText\":\"越王攻吳，王吳王謝而告服，越王欲許之，范蠡、大夫種曰：「不可。昔天以越與吳，吳不受，今天反夫差，亦天禍也。以吳予越，再拜受之，不可許也。」太宰嚭遺大夫種書曰：「狡兔盡則良犬烹，敵國滅則謀臣亡。大夫何不釋吳而患越乎？」大夫種受書讀之，太息而歎曰：「殺之，越與吳同命。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-31_s-1\",\"han-fei-zi_ch-31_p-31_s-2\",\"han-fei-zi_ch-31_p-31_s-3\",\"han-fei-zi_ch-31_p-31_s-4\",\"han-fei-zi_ch-31_p-31_s-5\",\"han-fei-zi_ch-31_p-31_s-6\",\"han-fei-zi_ch-31_p-31_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"越王攻吳，王吳王謝而且告服，越王欲許的，范蠡、大夫種說道：不可。昔天以越與吳，吳不受，今天反夫差，亦天禍啊。以吳予越，再拜受的，不可許啊。太宰嚭遺大夫種書說道：狡兔盡則良犬烹，敵國滅則謀臣下僚屬亡。大夫何不釋吳而且患越乎？大夫種受書讀的，太息而且歎說道：殺的，越與吳同命。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 31 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「越王攻吳，王吳王謝而告服，越王欲許之，范蠡、大夫種曰：「不可」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「越王攻吳，王吳王謝而告服，越王欲許之，范蠡、大夫種曰……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-32\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":32,\"canonicalText\":\"大成牛從趙謂申不害於韓曰：「以韓重我於趙，請以趙重子於韓，是子有兩韓，我有兩趙。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-32_s-1\",\"han-fei-zi_ch-31_p-32_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"大成牛從趙國來到韓國，對相國申不害說道：「希望您利用韓國的權勢在趙國提高我的聲望，我願利用趙國的權勢在韓國提高您的聲望。這樣一來，您在韓國既有本身地位又有趙國支援，如同擁有兩個韓國；我在趙國既有本身地位又有韓國支援，也如同擁有兩個趙國。」\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 32 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「大成牛從趙謂申不害於韓曰：「以韓重我於趙，請以趙重子於韓，是子有兩韓，我有兩趙」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「大成牛從趙謂申不害於韓曰：「以韓重我於趙，請以趙重子……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-33\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":33,\"canonicalText\":\"司馬喜，中山君之臣也，而善於趙，嘗以中山之謀微告趙王。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-33_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"司馬喜，中山君主統治者的臣下僚屬啊，而且善於趙，嘗以中山的謀微告趙王。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 33 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「司馬喜，中山君之臣也，而善於趙，嘗以中山之謀微告趙王」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「司馬喜，中山君之臣也，而善於趙，嘗以中山之謀微告趙王。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-34\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":34,\"canonicalText\":\"呂倉，魏王之臣也，而善於秦、荊，微諷秦、荊令之攻魏，因請行和以自重也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-34_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"呂倉，魏王的臣下僚屬啊，而且善於秦、荊，微諷秦、荊令的攻魏，因請行和以自重啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 34 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「呂倉，魏王之臣也，而善於秦、荊，微諷秦、荊令之攻魏，因請行和以自重也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「呂倉，魏王之臣也，而善於秦、荊，微諷秦、荊令之攻魏，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-35\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":35,\"canonicalText\":\"宋石，魏將也。衛君，荊將也。兩國搆難，二子皆將，宋石遺衛君書曰：「二軍相當，兩旗相望，唯毋一戰，戰必不兩存，此乃兩主之事也，與子無有私怨，善者相避也。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-35_s-1\",\"han-fei-zi_ch-31_p-35_s-2\",\"han-fei-zi_ch-31_p-35_s-3\",\"han-fei-zi_ch-31_p-35_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"宋石，魏將啊。衛君主統治者，荊將啊。兩國搆難，二子皆將，宋石遺衛君主統治者書說道：二軍相當，兩旗相望，唯毋一戰，戰必不兩存，此乃兩主的事啊，與子無有私怨，善的人或事物相避啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 35 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「宋石，魏將也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「宋石，魏將也。衛君，荊將也。兩國搆難，二子皆將，宋石……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-36\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":36,\"canonicalText\":\"白圭相魏，暴譴相韓。白圭謂暴譴曰：「子以韓輔我於魏，我請以魏待子於韓，臣長用魏，子長用韓。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-36_s-1\",\"han-fei-zi_ch-31_p-36_s-2\",\"han-fei-zi_ch-31_p-36_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"白圭相魏，暴譴相韓。白圭謂暴譴說道：子以韓輔我於魏，我請以魏待子於韓，臣下僚屬長用魏，子長用韓。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 36 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「白圭相魏，暴譴相韓」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「白圭相魏，暴譴相韓。白圭謂暴譴曰：「子以韓輔我於魏，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-37\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":37,\"canonicalText\":\"說三\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-37_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說三。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 37 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-38\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":38,\"canonicalText\":\"齊中大夫有夷射者，御飲於王，醉甚而出，倚於郎門，門者刖跪請曰：「足下無意賜之餘瀝乎？」夷射曰：「叱去！刑餘之人，何事乃敢乞飲長者？」刖跪走退，及夷射去，刖跪因捐水郎門霤下，類溺者之狀。明日，王出而訶之曰：「誰溺於是？」刖跪對曰：「臣不見也。雖然，昨日中大夫夷射立於此。」王因誅夷射而殺之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-38_s-1\",\"han-fei-zi_ch-31_p-38_s-2\",\"han-fei-zi_ch-31_p-38_s-3\",\"han-fei-zi_ch-31_p-38_s-4\",\"han-fei-zi_ch-31_p-38_s-5\",\"han-fei-zi_ch-31_p-38_s-6\",\"han-fei-zi_ch-31_p-38_s-7\",\"han-fei-zi_ch-31_p-38_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊中大夫有夷射的人或事物，御飲於王，醉甚而且出，倚於郎門，門的人或事物刖跪請說道：足下無意賜的餘瀝乎？夷射說道：叱去！刑餘的人，何事乃敢乞飲長的人或事物？刖跪走退，及夷射去，刖跪因捐水郎門霤下，類溺的人或事物的狀。明日，王出而且訶的說道：誰溺於是？刖跪對說道：臣下僚屬不見啊。雖然，昨日中大夫夷射立於此。王因誅夷射而且殺的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 38 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊中大夫有夷射者，御飲於王，醉甚而出，倚於郎門，門者刖跪請曰：「足下無意賜之餘瀝乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊中大夫有夷射者，御飲於王，醉甚而出，倚於郎門，門者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-39\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":39,\"canonicalText\":\"魏王臣二人不善濟陽君，濟陽君因偽令人矯王命而謀攻己，王使人問濟陽君曰：「誰與恨？」對曰：「無敢與恨，雖然，嘗與二人不善，不足以至於此。」王問左右，左右曰：「固然。」王因誅二人者。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-39_s-1\",\"han-fei-zi_ch-31_p-39_s-2\",\"han-fei-zi_ch-31_p-39_s-3\",\"han-fei-zi_ch-31_p-39_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏王臣下僚屬二人不善濟陽君主統治者，濟陽君主統治者因偽令人矯王命而且謀攻己，王使人問濟陽君主統治者說道：誰與恨？對說道：無敢與恨，雖然，嘗與二人不善，不足以至於此。王問左右，左右說道：固然。王因誅二人的人或事物。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 39 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魏王臣二人不善濟陽君，濟陽君因偽令人矯王命而謀攻己，王使人問濟陽君曰：「誰與恨」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魏王臣二人不善濟陽君，濟陽君因偽令人矯王命而謀攻己，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-40\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":40,\"canonicalText\":\"季辛與爰騫相怨。司馬喜新與季辛惡，因微令人殺爰騫，中山之君以為季辛也，因誅之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-40_s-1\",\"han-fei-zi_ch-31_p-40_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"季辛與爰騫相怨。司馬喜新與季辛惡，因微令人殺爰騫，中山的君主統治者以為季辛啊，因誅的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 40 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「季辛與爰騫相怨」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「季辛與爰騫相怨。司馬喜新與季辛惡，因微令人殺爰騫，中……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-41\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":41,\"canonicalText\":\"荊王所愛妾有鄭袖者。荊王新得美女，鄭袖因教之曰：「王甚喜人之掩口也，為近王，必掩口。」美女入見，近王，因掩口，王問其故，鄭袖曰：「此固言惡王之臭。」及王與鄭袖、美女三人坐，袖因先誡御者曰：「王適有言，必亟聽從。」王言美女前，近王，甚數掩口，王悖然怒曰：「劓之。」御因揄刀而劓美人。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-41_s-1\",\"han-fei-zi_ch-31_p-41_s-2\",\"han-fei-zi_ch-31_p-41_s-3\",\"han-fei-zi_ch-31_p-41_s-4\",\"han-fei-zi_ch-31_p-41_s-5\",\"han-fei-zi_ch-31_p-41_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"荊王所愛妾有鄭袖的人或事物。荊王新得美女，鄭袖因教的說道：王甚喜人的掩口啊，為近王，必掩口。美女入見，近王，因掩口，王問他的所以，鄭袖說道：此固言惡王的臭。及王與鄭袖、美女三人坐，袖因先誡御的人或事物說道：王適有言，必亟聽從。王言美女前，近王，甚數掩口，王悖然怒說道：劓的。御因揄刀而且劓美人。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 41 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「荊王所愛妾有鄭袖者」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「荊王所愛妾有鄭袖者。荊王新得美女，鄭袖因教之曰：「王……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-42\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":42,\"canonicalText\":\"一曰。魏王遺荊王美人，荊王甚悅之，夫人鄭袖知王悅愛之也，亦悅愛之，甚於王，衣服玩好擇其所欲為之，王曰：「夫人知我愛新人也，其悅愛之甚於寡人，此孝子所以養親，忠臣之所以事君也。」夫人知王之不以己為妒也，因為新人曰：「王甚悅愛子，然惡子之鼻，子見王，常掩鼻，則王長幸子矣。」於是新人從之，每見王，常掩鼻，王謂夫人曰：「新人見寡人常掩鼻何也？」對曰：「不己知也。」王強問之，對曰：「頃嘗言惡聞王臭。」王怒曰：「劓之。」夫人先誡御者曰：「王適有言，必可從命。」御者因揄刀而劓美人。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-42_s-1\",\"han-fei-zi_ch-31_p-42_s-2\",\"han-fei-zi_ch-31_p-42_s-3\",\"han-fei-zi_ch-31_p-42_s-4\",\"han-fei-zi_ch-31_p-42_s-5\",\"han-fei-zi_ch-31_p-42_s-6\",\"han-fei-zi_ch-31_p-42_s-7\",\"han-fei-zi_ch-31_p-42_s-8\",\"han-fei-zi_ch-31_p-42_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。魏王遺荊王美人，荊王甚悅的，夫人鄭袖知王悅愛的啊，亦悅愛的，甚於王，衣服玩好擇他的所欲為的，王說道：夫人知我愛新人啊，他的悅愛的甚於寡人，此孝子所以養親，忠臣下僚屬的所以事君主統治者啊。夫人知王的不以己為妒啊，因為新人說道：王甚悅愛子，然惡子的鼻，子見王，常掩鼻，則王長幸子矣。於是新人從的，每見王，常掩鼻，王謂夫人說道：新人見寡人常掩鼻何啊？對說道：不己知啊。王強問的，對說道：頃嘗言惡聞王臭。王怒說道：劓的。夫人先誡御的人或事物說道：王適有言，必可從命。御的人或事物因揄刀而且劓美人。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 42 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。魏王遺荊王美人，荊王甚悅之，夫人鄭袖知王悅愛之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-43\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":43,\"canonicalText\":\"費無極，荊令尹之近者也。郤宛新事令尹，令尹甚愛之，無極因謂令尹曰：「君愛宛甚，何不一為酒其家？」令尹曰：「善。」因令之為具於郤宛之家。無極教宛曰：「令尹甚傲而好兵，子必謹敬，先亟陳兵堂下及門庭。」宛因為之。令尹往而大驚曰：「此何也？」無極曰：「君殆去之，事未可知也。」令尹大怒，舉兵而誅郤宛，遂殺之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-43_s-1\",\"han-fei-zi_ch-31_p-43_s-2\",\"han-fei-zi_ch-31_p-43_s-3\",\"han-fei-zi_ch-31_p-43_s-4\",\"han-fei-zi_ch-31_p-43_s-5\",\"han-fei-zi_ch-31_p-43_s-6\",\"han-fei-zi_ch-31_p-43_s-7\",\"han-fei-zi_ch-31_p-43_s-8\",\"han-fei-zi_ch-31_p-43_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"費無極，荊令尹的近的人或事物啊。郤宛新事令尹，令尹甚愛的，無極因謂令尹說道：君主統治者愛宛甚，何不一為酒他的家？令尹說道：善。因令的為具於郤宛的家。無極教宛說道：令尹甚傲而且好兵，子必謹敬，先亟陳兵堂下及門庭。宛因為的。令尹往而且大驚說道：此何啊？無極說道：君主統治者殆去的，事未可知啊。令尹大怒，舉兵而且誅郤宛，遂殺的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 43 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「費無極，荊令尹之近者也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「費無極，荊令尹之近者也。郤宛新事令尹，令尹甚愛之，無……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-44\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":44,\"canonicalText\":\"犀首與張壽為怨，陳需新入，不善犀首，因使人微殺張壽，魏王以為犀首也，乃誅之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-44_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"犀首（公孫衍）與張壽結下私怨，陳需新近入仕魏國，素來與犀首不和。陳需於是暗中指使刺客暗殺了張壽；魏惠王以為刺殺張壽的人必定是犀首，於是下令誅殺了犀首。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 44 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「犀首與張壽為怨，陳需新入，不善犀首，因使人微殺張壽，魏王以為犀首也，乃誅之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「犀首與張壽為怨，陳需新入，不善犀首，因使人微殺張壽，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-45\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":45,\"canonicalText\":\"中山有賤公子，馬甚瘦，車甚弊，左右有私不善者，乃為之請王曰：「公子甚貧，馬甚瘦，王何不益之馬食？」王不許，左右因微令夜燒芻廄，王以為賤公子也，乃誅之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-45_s-1\",\"han-fei-zi_ch-31_p-45_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"中山有賤公子，馬甚瘦，車甚弊，左右有私不善的人或事物，乃為的請王說道：公子甚貧，馬甚瘦，王何不益的馬食？王不許，左右因微令夜燒芻廄，王以為賤公子啊，乃誅的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 45 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「中山有賤公子，馬甚瘦，車甚弊，左右有私不善者，乃為之請王曰：「公子甚貧，馬甚瘦，王何不益之馬食」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「中山有賤公子，馬甚瘦，車甚弊，左右有私不善者，乃為之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-46\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":46,\"canonicalText\":\"魏有老儒而不善濟陽君，客有與老儒私怨者，因攻老儒殺之以德於濟陽君曰：「臣為其不善君也，故為君殺之。」濟陽君因不察而賞之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-46_s-1\",\"han-fei-zi_ch-31_p-46_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏有老儒而且不善濟陽君主統治者，客有與老儒私怨的人或事物，因攻老儒殺的以德於濟陽君主統治者說道：臣下僚屬為他的不善君主統治者啊，所以為君主統治者殺的。濟陽君主統治者因不察而且賞賜恩惠的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 46 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魏有老儒而不善濟陽君，客有與老儒私怨者，因攻老儒殺之以德於濟陽君曰：「臣為其不善君也，故為君殺之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魏有老儒而不善濟陽君，客有與老儒私怨者，因攻老儒殺之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-47\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":47,\"canonicalText\":\"一曰。濟陽君有少庶子，有不見知，欲入愛於君者，齊使老儒掘藥於馬梨之山，濟陽少庶子欲以為功，入見於君曰：「齊使老儒掘藥於馬梨之山，名掘藥也，實閒君之國，君殺之，是將以濟陽君抵罪於齊矣。臣請刺之。」君曰：「可。」於是明日得之城陰而刺之，濟陽君還益親之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-47_s-1\",\"han-fei-zi_ch-31_p-47_s-2\",\"han-fei-zi_ch-31_p-47_s-3\",\"han-fei-zi_ch-31_p-47_s-4\",\"han-fei-zi_ch-31_p-47_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。濟陽君主統治者有少庶子，有不見知，欲入愛於君主統治者的人或事物，齊使老儒掘藥於馬梨的山，濟陽少庶子欲以為功，入見於君主統治者說道：齊使老儒掘藥於馬梨的山，名掘藥啊，實閒君主統治者的國，君主統治者殺的，是將以濟陽君主統治者抵罪於齊矣。臣下僚屬請刺的。君主統治者說道：可。於是明日得的城陰而且刺的，濟陽君主統治者還益親的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 47 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。濟陽君有少庶子，有不見知，欲入愛於君者，齊使老……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-48\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":48,\"canonicalText\":\"說四\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-48_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說四。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 48 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說四」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說四」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-49\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":49,\"canonicalText\":\"陳需，魏王之臣也，善於荊王，而令荊攻魏，荊攻魏，陳需因請為魏王行解之，因以荊勢相魏。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-49_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"陳需，魏王的臣下僚屬啊，善於荊王，而且令荊攻魏，荊攻魏，陳需因請為魏王行解的，因以荊至高權力威勢相魏。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 49 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「陳需，魏王之臣也，善於荊王，而令荊攻魏，荊攻魏，陳需因請為魏王行解之，因以荊勢相魏」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「陳需，魏王之臣也，善於荊王，而令荊攻魏，荊攻魏，陳需……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-50\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":50,\"canonicalText\":\"韓昭侯之時，黍種嘗貴甚，昭侯令人覆廩，吏果竊黍種而糶之甚多。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-50_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"韓昭侯的時，黍種嘗貴甚，昭侯令人覆廩，吏果竊黍種而且糶的甚多。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 50 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「韓昭侯之時，黍種嘗貴甚，昭侯令人覆廩，吏果竊黍種而糶之甚多」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「韓昭侯之時，黍種嘗貴甚，昭侯令人覆廩，吏果竊黍種而糶……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-51\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":51,\"canonicalText\":\"昭奚恤之用荊也，有燒倉廥窌者，而不知其人，昭奚恤令吏執販茅者而問之，果燒也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-51_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昭奚恤的用荊啊，有燒倉廥窌的人或事物，而且不知他的人，昭奚恤令吏執販茅的人或事物而且問的，果燒啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 51 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「昭奚恤之用荊也，有燒倉廥窌者，而不知其人，昭奚恤令吏執販茅者而問之，果燒也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「昭奚恤之用荊也，有燒倉廥窌者，而不知其人，昭奚恤令吏……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-52\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":52,\"canonicalText\":\"昭僖侯之時，宰人上食而羹中有生肝焉。昭侯召宰人之次而誚之曰：「若何為置生肝寡人羹中？」宰人頓首服死罪曰：「竊欲去尚宰人也。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-52_s-1\",\"han-fei-zi_ch-31_p-52_s-2\",\"han-fei-zi_ch-31_p-52_s-3\",\"han-fei-zi_ch-31_p-52_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昭僖侯的時，宰人上食而且羹中有生肝焉。昭侯召宰人的次而且誚的說道：若何為置生肝寡人羹中？宰人頓首服死罪說道：竊欲去尚宰人啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 52 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「昭僖侯之時，宰人上食而羹中有生肝焉」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「昭僖侯之時，宰人上食而羹中有生肝焉。昭侯召宰人之次而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-53\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":53,\"canonicalText\":\"一曰。僖侯浴，湯中有礫，僖侯曰：「尚浴免則有當代者乎？」左右對曰：「有。」僖侯曰：「召而來。」譙之曰：「何為置礫湯中？」對曰：「尚浴免，則臣得代之，是以置礫湯中。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-53_s-1\",\"han-fei-zi_ch-31_p-53_s-2\",\"han-fei-zi_ch-31_p-53_s-3\",\"han-fei-zi_ch-31_p-53_s-4\",\"han-fei-zi_ch-31_p-53_s-5\",\"han-fei-zi_ch-31_p-53_s-6\",\"han-fei-zi_ch-31_p-53_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。僖侯浴，湯中有礫，僖侯說道：尚浴免則有當代的人或事物乎？左右對說道：有。僖侯說道：召而且來。譙的說道：何為置礫湯中？對說道：尚浴免，則臣下僚屬得代的，是以置礫湯中。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 53 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。僖侯浴，湯中有礫，僖侯曰：「尚浴免則有當代者乎……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-54\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":54,\"canonicalText\":\"文公之時，宰臣上炙而髮繞之，文公召宰人而譙之曰：「女欲寡人之哽邪？奚為以髮繞炙。」宰人頓首再拜請曰：「臣有死罪三：援礪砥刀，利猶幹將也，切肉，肉斷而髮不斷，臣之罪一也；援木而貫臠而不見髮，臣之罪二也；奉熾爐，炭火盡赤紅，而炙熟而髮不燒，臣之罪三也。堂下得無微有疾臣者乎？」公曰：「善。」乃召其堂下而譙之，果然，乃誅之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-54_s-1\",\"han-fei-zi_ch-31_p-54_s-2\",\"han-fei-zi_ch-31_p-54_s-3\",\"han-fei-zi_ch-31_p-54_s-4\",\"han-fei-zi_ch-31_p-54_s-5\",\"han-fei-zi_ch-31_p-54_s-6\",\"han-fei-zi_ch-31_p-54_s-7\",\"han-fei-zi_ch-31_p-54_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"文公的時，宰臣下僚屬上炙而且髮繞的，文公召宰人而且譙的說道：女欲寡人的哽邪？奚為以髮繞炙。宰人頓首再拜請說道：臣下僚屬有死罪三：援礪砥刀，利猶幹將啊，切肉，肉斷而且髮不斷，臣下僚屬的罪一啊；援木而且貫臠而且不見髮，臣下僚屬的罪二啊；奉熾爐，炭火盡赤紅，而且炙熟而且髮不燒，臣下僚屬的罪三啊。堂下得無微有疾臣下僚屬的人或事物乎？公說道：善。乃召他的堂下而且譙的，果然，乃誅的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 54 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「文公之時，宰臣上炙而髮繞之，文公召宰人而譙之曰：「女欲寡人之哽邪」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「文公之時，宰臣上炙而髮繞之，文公召宰人而譙之曰：「女……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-55\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":55,\"canonicalText\":\"一曰。晉平公觴客，少庶子進炙而髮繞之，平公趣殺炮人，毋有反令，炮人呼天曰：「嗟乎！臣有三罪，死而不自知乎？」平公曰：「何謂也？」對曰：「臣刀之利，風靡骨斷而髮不斷，是臣之一死也；桑炭炙之，肉紅白而髮不焦，是臣之二死也；炙熟又重睫而視之，髮繞炙而目不見，是臣之三死也。意者堂下其有翳憎臣者乎？殺臣不亦蚤乎！」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-55_s-1\",\"han-fei-zi_ch-31_p-55_s-2\",\"han-fei-zi_ch-31_p-55_s-3\",\"han-fei-zi_ch-31_p-55_s-4\",\"han-fei-zi_ch-31_p-55_s-5\",\"han-fei-zi_ch-31_p-55_s-6\",\"han-fei-zi_ch-31_p-55_s-7\",\"han-fei-zi_ch-31_p-55_s-8\",\"han-fei-zi_ch-31_p-55_s-9\",\"han-fei-zi_ch-31_p-55_s-10\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。晉平公觴客，少庶子進炙而且髮繞的，平公趣殺炮人，毋有反令，炮人呼天說道：嗟乎！臣下僚屬有三罪，死而且不自知乎？平公說道：何謂啊？對說道：臣下僚屬刀的利，風靡骨斷而且髮不斷，是臣下僚屬的一死啊；桑炭炙的，肉紅白而且髮不焦，是臣下僚屬的二死啊；炙熟又重睫而且視的，髮繞炙而且目不見，是臣下僚屬的三死啊。意的人或事物堂下他的有翳憎臣下僚屬的人或事物乎？殺臣下僚屬不亦蚤乎！\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 55 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。晉平公觴客，少庶子進炙而髮繞之，平公趣殺炮人，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-56\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":56,\"canonicalText\":\"穰侯相秦而齊強，穰侯欲立秦為帝而齊不聽，因請立齊為東帝而不能成也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-56_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"穰侯魏冉在秦國擔任相國，當時齊國勢力十分強盛。穰侯企圖尊立秦昭王為帝號，而齊國拒絕答應；穰侯於是轉而請求尊立齊湣王為東帝，最後這項尊帝的企圖終究未能成功。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 56 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「穰侯相秦而齊強，穰侯欲立秦為帝而齊不聽，因請立齊為東帝而不能成也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「穰侯相秦而齊強，穰侯欲立秦為帝而齊不聽，因請立齊為東……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-57\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":57,\"canonicalText\":\"說五\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-57_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說五。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 57 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說五」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說五」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-58\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":58,\"canonicalText\":\"晉獻公之時，驪姬貴，擬於後妻，而欲以其子奚齊代太子申生，因患申生於君而殺之，遂立奚齊為太子。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-58_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"晉獻公的時，驪姬貴，擬於後妻，而且欲以他的子奚齊代太子申生，因患申生於君主統治者而且殺的，遂立奚齊為太子。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 58 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「晉獻公之時，驪姬貴，擬於後妻，而欲以其子奚齊代太子申生，因患申生於君而殺之，遂立奚齊為太子」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「晉獻公之時，驪姬貴，擬於後妻，而欲以其子奚齊代太子申……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-59\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":59,\"canonicalText\":\"鄭君已立太子矣，而有所愛美女欲以其子為後，夫人恐，因用毒藥賊君殺之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-59_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鄭君主統治者已立太子矣，而且有所愛美女欲以他的子為後，夫人恐，因用毒藥賊君主統治者殺的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 59 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「鄭君已立太子矣，而有所愛美女欲以其子為後，夫人恐，因用毒藥賊君殺之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「鄭君已立太子矣，而有所愛美女欲以其子為後，夫人恐，因……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-60\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":60,\"canonicalText\":\"衛州籲重於衛，擬於君，群臣百姓盡畏其勢重，州籲果殺其君而奪之政。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-60_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛州籲重於衛，擬於君主統治者，群臣下僚屬百姓盡畏他的至高權力威勢重，州籲果殺他的君主統治者而且奪的政。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 60 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛州籲重於衛，擬於君，群臣百姓盡畏其勢重，州籲果殺其君而奪之政」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛州籲重於衛，擬於君，群臣百姓盡畏其勢重，州籲果殺其……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-61\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":61,\"canonicalText\":\"公子朝，周太子也，弟公子根甚有寵於君，君死，遂以東周叛，分為兩國。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-61_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公子朝，周太子啊，弟公子根甚有寵於君主統治者，君主統治者死，遂以東周叛，分為兩國。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 61 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「公子朝，周太子也，弟公子根甚有寵於君，君死，遂以東周叛，分為兩國」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「公子朝，周太子也，弟公子根甚有寵於君，君死，遂以東周……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-62\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":62,\"canonicalText\":\"楚成王以商臣為太子，既而又欲置公子職。商臣作亂，遂攻殺成王。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-62_s-1\",\"han-fei-zi_ch-31_p-62_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚成王以商臣下僚屬為太子，既而且又欲置公子職。商臣下僚屬作亂，遂攻殺成王。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 62 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「楚成王以商臣為太子，既而又欲置公子職」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「楚成王以商臣為太子，既而又欲置公子職。商臣作亂，遂攻……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-63\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":63,\"canonicalText\":\"一曰。楚成王商臣為太子，既欲置公子職。商臣聞之，未察也，乃為其傅潘崇曰：「奈何察之也？」潘崇曰：「饗江芊而勿敬也。」太子聽之。江芊曰：「呼役夫！宜君王之慾廢女而立職也。」商臣曰：「信矣。」潘崇曰：「能事之乎？」曰：「不能。」「能為之諸侯乎？」曰：「不能。」「能舉大事乎？」曰：「能。」於是乃起宿營之甲而攻成王，成王請食能膰而死，不許，遂自殺。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-63_s-1\",\"han-fei-zi_ch-31_p-63_s-2\",\"han-fei-zi_ch-31_p-63_s-3\",\"han-fei-zi_ch-31_p-63_s-4\",\"han-fei-zi_ch-31_p-63_s-5\",\"han-fei-zi_ch-31_p-63_s-6\",\"han-fei-zi_ch-31_p-63_s-7\",\"han-fei-zi_ch-31_p-63_s-8\",\"han-fei-zi_ch-31_p-63_s-9\",\"han-fei-zi_ch-31_p-63_s-10\",\"han-fei-zi_ch-31_p-63_s-11\",\"han-fei-zi_ch-31_p-63_s-12\",\"han-fei-zi_ch-31_p-63_s-13\",\"han-fei-zi_ch-31_p-63_s-14\",\"han-fei-zi_ch-31_p-63_s-15\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。楚成王商臣下僚屬為太子，既欲置公子職。商臣下僚屬聞的，未察啊，乃為他的傅潘崇說道：奈何察的啊？潘崇說道：饗江芊而且勿敬啊。太子聽的。江芊說道：呼役夫！宜君主統治者王的慾廢女而且立職啊。商臣下僚屬說道：信矣。潘崇說道：能事的乎？說道：不能。能為的諸侯乎？能舉大事乎？說道：能。於是乃起宿營的甲而且攻成王，成王請食能膰而且死，不許，遂自殺。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 63 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。楚成王商臣為太子，既欲置公子職。商臣聞之，未察……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-64\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":64,\"canonicalText\":\"韓廆相韓哀侯，嚴遂重於君，二人甚相害也，嚴遂乃令人刺韓廆於朝，韓廆走君而抱之，遂刺韓廆而兼哀侯。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-64_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"韓廆相韓哀侯，嚴遂重於君主統治者，二人甚相害啊，嚴遂乃令人刺韓廆於朝，韓廆走君主統治者而且抱的，遂刺韓廆而且兼哀侯。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 64 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「韓廆相韓哀侯，嚴遂重於君，二人甚相害也，嚴遂乃令人刺韓廆於朝，韓廆走君而抱之，遂刺韓廆而兼哀侯」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「韓廆相韓哀侯，嚴遂重於君，二人甚相害也，嚴遂乃令人刺……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-65\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":65,\"canonicalText\":\"田恆相齊，闞止重於簡公，二人相憎而欲相賊也，田恆因行私惠以取其國，遂殺簡公而奪之政。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-65_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"田恆相齊，闞止重於簡公，二人相憎而且欲相賊啊，田恆因行私惠以取他的國，遂殺簡公而且奪的政。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 65 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「田恆相齊，闞止重於簡公，二人相憎而欲相賊也，田恆因行私惠以取其國，遂殺簡公而奪之政」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「田恆相齊，闞止重於簡公，二人相憎而欲相賊也，田恆因行……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-66\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":66,\"canonicalText\":\"戴驩為宋太宰，皇喜重於君，二人爭事而相害也，皇喜遂殺宋君而奪其政。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-66_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"戴驩為宋太宰，皇喜重於君主統治者，二人爭事而且相害啊，皇喜遂殺宋君主統治者而且奪他的政。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 66 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「戴驩為宋太宰，皇喜重於君，二人爭事而相害也，皇喜遂殺宋君而奪其政」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「戴驩為宋太宰，皇喜重於君，二人爭事而相害也，皇喜遂殺……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-67\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":67,\"canonicalText\":\"狐突曰：「國君好內則太子危，好外則相室危。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-67_s-1\",\"han-fei-zi_ch-31_p-67_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"狐突說道：國君主統治者好內則太子危，好外則相室危。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 67 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「狐突曰：「國君好內則太子危，好外則相室危」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「狐突曰：「國君好內則太子危，好外則相室危。」」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-68\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":68,\"canonicalText\":\"鄭君問鄭昭曰：「太子亦何如？」對曰：「太子未生也。」君曰：「太子已置而曰未生何也？」對曰：「太子雖置，然而君之好色不已，所愛有子，君必愛之，愛之則必欲以為後，臣故曰太子未生也。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-68_s-1\",\"han-fei-zi_ch-31_p-68_s-2\",\"han-fei-zi_ch-31_p-68_s-3\",\"han-fei-zi_ch-31_p-68_s-4\",\"han-fei-zi_ch-31_p-68_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鄭君主統治者問鄭昭說道：太子亦何如？對說道：太子未生啊。君主統治者說道：太子已置而且說道：未生何啊？對說道：太子雖置，然而且君主統治者的好色不已，所愛有子，君主統治者必愛的，愛的則必欲以為後，臣下僚屬因此韓絕不是子評論說道：太子未生啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 68 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「鄭君問鄭昭曰：「太子亦何如」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「鄭君問鄭昭曰：「太子亦何如？」對曰：「太子未生也。」……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-69\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":69,\"canonicalText\":\"說六\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-69_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說六。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 69 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說六」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說六」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-70\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":70,\"canonicalText\":\"文王資費仲而遊於紂之旁，令之諫紂而亂其心。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-70_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"文王資費仲而且遊於紂的旁，令的諫紂而且亂他的心。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 70 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「文王資費仲而遊於紂之旁，令之諫紂而亂其心」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「文王資費仲而遊於紂之旁，令之諫紂而亂其心。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-71\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":71,\"canonicalText\":\"荊王使人之秦，秦王甚禮之。王曰：「敵國有賢者，國之憂也。今荊王之使者甚賢，寡人患之。」群臣諫曰：「以王之賢聖與國之資厚，願荊王之賢人。王何不深知之而陰有之，荊以為外用也，則必誅之。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-71_s-1\",\"han-fei-zi_ch-31_p-71_s-2\",\"han-fei-zi_ch-31_p-71_s-3\",\"han-fei-zi_ch-31_p-71_s-4\",\"han-fei-zi_ch-31_p-71_s-5\",\"han-fei-zi_ch-31_p-71_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"荊王使人的秦，秦王甚禮的。王說道：敵國有賢的人或事物，國的憂啊。今荊王的使的人或事物甚賢，寡人患的。群臣下僚屬諫說道：以王的賢聖與國的資厚，願荊王的賢人。王何不深知的而且陰有的，荊以為外用啊，則必誅的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 71 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「荊王使人之秦，秦王甚禮之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「荊王使人之秦，秦王甚禮之。王曰：「敵國有賢者，國之憂……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-72\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":72,\"canonicalText\":\"仲尼為政於魯，道不拾遺，齊景公患之，梨且謂景公曰：「去仲尼猶吹毛耳。君何不迎之以重祿高位，遺哀公女樂以驕榮其意。哀公新樂之，必怠於政，仲尼必諫，諫必輕絕於魯。」景公曰：「善。」乃令梨且以女樂二八遺哀公，哀公樂之，果怠於政，仲尼諫，不聽，去而之楚。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-72_s-1\",\"han-fei-zi_ch-31_p-72_s-2\",\"han-fei-zi_ch-31_p-72_s-3\",\"han-fei-zi_ch-31_p-72_s-4\",\"han-fei-zi_ch-31_p-72_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"仲尼為政於魯，道不拾遺，齊景公患的，梨且謂景公說道：去仲尼猶吹毛耳。君主統治者何不迎的以重祿高位，遺哀公女樂以驕榮他的意。哀公新樂的，必怠於政，仲尼必諫，諫必輕絕於魯。景公說道：善。乃令梨且以女樂二八遺哀公，哀公樂的，果怠於政，仲尼諫，不聽，去而且的楚。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 72 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「仲尼為政於魯，道不拾遺，齊景公患之，梨且謂景公曰：「去仲尼猶吹毛耳」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「仲尼為政於魯，道不拾遺，齊景公患之，梨且謂景公曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-73\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":73,\"canonicalText\":\"楚王謂乾象曰：「吾欲以楚扶甘茂而相之秦可乎？」乾象對曰：「不可也。」王曰：「何也？」曰：「甘茂少而事史舉先生，史舉，上蔡之監門也，大不事君，小不事家，以苛刻聞天下，茂事之順焉。惠王之明，張儀之辨也，茂事之，取十官而免於罪，是茂賢也。」王曰：「相人敵國而相賢，其不可何也？」乾象曰：「前時王使邵滑之越，五年而能亡越，所以然者，越亂而楚治也。日者知用之越，今亡之秦，不亦太亟忘乎！」王曰：「然則為之奈何？」乾象對曰：「不如相共立。」王曰：「共立可相何也？」對曰：「共立少見愛幸，長為貴卿，被王衣，含杜若，握玉環，以聽於朝。且利以亂秦矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-73_s-1\",\"han-fei-zi_ch-31_p-73_s-2\",\"han-fei-zi_ch-31_p-73_s-3\",\"han-fei-zi_ch-31_p-73_s-4\",\"han-fei-zi_ch-31_p-73_s-5\",\"han-fei-zi_ch-31_p-73_s-6\",\"han-fei-zi_ch-31_p-73_s-7\",\"han-fei-zi_ch-31_p-73_s-8\",\"han-fei-zi_ch-31_p-73_s-9\",\"han-fei-zi_ch-31_p-73_s-10\",\"han-fei-zi_ch-31_p-73_s-11\",\"han-fei-zi_ch-31_p-73_s-12\",\"han-fei-zi_ch-31_p-73_s-13\",\"han-fei-zi_ch-31_p-73_s-14\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚王謂乾象說道：吾欲以楚扶甘茂而且相的秦可乎？乾象對說道：不可啊。王說道：何啊？說道：甘茂少而且事史舉先生，史舉，上蔡的監門啊，大不事君主統治者，小不事家，以苛刻聞天下，茂事的順焉。惠王的明，張儀的辨啊，茂事的，取十官而且免於罪，是茂賢啊。王說道：相人敵國而且相賢，他的不可何啊？乾象說道：前時王使邵滑的越，五年而且能亡越，所以然的人或事物，越亂而且楚治啊。日的人或事物知用的越，今亡的秦，不亦太亟忘乎！王說道：然則為的奈何？乾象對說道：不如相共立。王說道：共立可相何啊？對說道：共立少見愛幸，長為貴卿，被王衣，含杜若，握玉環，以聽於朝。且利以亂秦矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 73 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「楚王謂乾象曰：「吾欲以楚扶甘茂而相之秦可乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「楚王謂乾象曰：「吾欲以楚扶甘茂而相之秦可乎？」乾象對……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-74\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":74,\"canonicalText\":\"吳政荊，子胥使人宣言於荊曰：「子期用，將擊之。子常用，將去之。」荊人聞之，因用子常而退子期也。吳人擊之，遂勝之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-74_s-1\",\"han-fei-zi_ch-31_p-74_s-2\",\"han-fei-zi_ch-31_p-74_s-3\",\"han-fei-zi_ch-31_p-74_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"吳政荊，子胥使人宣言於荊說道：子期用，將擊的。子常用，將去的。荊人聞的，因用子常而且退子期啊。吳人擊的，遂勝的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 74 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「吳政荊，子胥使人宣言於荊曰：「子期用，將擊之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「吳政荊，子胥使人宣言於荊曰：「子期用，將擊之。子常用……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-75\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":75,\"canonicalText\":\"晉獻公伐虞、虢，乃遺之屈產之乘，垂棘之璧，女樂二八，以榮其意而亂其政。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-75_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"晉獻公伐虞、虢，乃遺的屈產的乘，垂棘的璧，女樂二八，以榮他的意而且亂他的政。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 75 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「晉獻公伐虞、虢，乃遺之屈產之乘，垂棘之璧，女樂二八，以榮其意而亂其政」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「晉獻公伐虞、虢，乃遺之屈產之乘，垂棘之璧，女樂二八，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-76\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":76,\"canonicalText\":\"叔向之讒萇弘也，為書曰：「萇弘謂叔向曰：子為我謂晉君，所與君期者時可矣，何不亟以兵來？」因佯遺其書周君之庭而急去行，周以萇弘為賣周也，乃誅萇弘而殺之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-76_s-1\",\"han-fei-zi_ch-31_p-76_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"叔向的讒萇弘啊，為書說道：萇弘謂叔向說道：子為我謂晉君主統治者，所與君主統治者期的人或事物時可矣，何不亟以兵來？因佯遺他的書周君主統治者的庭而且急去行，周以萇弘為賣周啊，乃誅萇弘而且殺的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 76 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「叔向之讒萇弘也，為書曰：「萇弘謂叔向曰：子為我謂晉君，所與君期者時可矣，何不亟以兵來」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「叔向之讒萇弘也，為書曰：「萇弘謂叔向曰：子為我謂晉君……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-77\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":77,\"canonicalText\":\"鄭桓公將欲襲鄶，先問鄶之豪傑良臣辯智果敢之士，盡與其姓名，擇鄶之良田賂之，為官爵之名而書之，因為設壇場郭門之外而埋之，釁之以雞豭，若盟狀。鄶君以為內難也而盡殺其良臣，桓公襲鄶，遂取之。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-77_s-1\",\"han-fei-zi_ch-31_p-77_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鄭桓公將欲襲鄶，先問鄶的豪傑良臣下僚屬辯智果敢的士，盡與他的姓名，擇鄶的良田賂的，為官爵的名而且書的，因為設壇場郭門的外而且埋的，釁的以雞豭，若盟狀。鄶君主統治者以為內難啊而且盡殺他的良臣下僚屬，桓公襲鄶，遂取的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 77 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「鄭桓公將欲襲鄶，先問鄶之豪傑良臣辯智果敢之士，盡與其姓名，擇鄶之良田賂之，為官爵之名而書之，因為設壇場郭門之外而埋之，釁之以雞豭，若盟狀」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「鄭桓公將欲襲鄶，先問鄶之豪傑良臣辯智果敢之士，盡與其……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-78\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":78,\"canonicalText\":\"說七\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-78_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說七。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 78 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說七」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說七」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-79\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":79,\"canonicalText\":\"七秦侏儒善於荊王，而陰有善荊王左右而內重於惠文君，荊適有謀，侏儒常先聞之以告惠文君。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-79_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"七秦侏儒善於荊王，而且陰有善荊王左右而且內重於惠文君主統治者，荊適有謀，侏儒常先聞的以告惠文君主統治者。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 79 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「七秦侏儒善於荊王，而陰有善荊王左右而內重於惠文君，荊適有謀，侏儒常先聞之以告惠文君」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「七秦侏儒善於荊王，而陰有善荊王左右而內重於惠文君，荊……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-80\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":80,\"canonicalText\":\"鄴令襄疵，陰善趙王左右，趙王謀襲鄴，襄疵常輒聞而先言之魏王，魏王備之，趙乃輒還。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-80_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鄴令襄疵，陰善趙王左右，趙王謀襲鄴，襄疵常輒聞而且先言的魏王，魏王備的，趙乃輒還。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 80 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「鄴令襄疵，陰善趙王左右，趙王謀襲鄴，襄疵常輒聞而先言之魏王，魏王備之，趙乃輒還」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「鄴令襄疵，陰善趙王左右，趙王謀襲鄴，襄疵常輒聞而先言……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-31_p-81\",\"chapterId\":\"han-fei-zi_ch-31\",\"order\":81,\"canonicalText\":\"衛嗣君之時，有人於令之左右，縣令有發蓐而席弊甚，嗣公還令人遺之席曰：「吾聞汝今者發蓐而席弊甚，賜汝席。」縣令大驚，以君為神也。\",\"sentenceIds\":[\"han-fei-zi_ch-31_p-81_s-1\",\"han-fei-zi_ch-31_p-81_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛嗣君主統治者的時，有人於令的左右，縣令有發蓐而且席弊甚，嗣公還令人遺的席說道：吾聞汝今的人或事物發蓐而且席弊甚，賜汝席。縣令大驚，以君主統治者為神啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說下〉（第 81 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛嗣君之時，有人於令之左右，縣令有發蓐而席弊甚，嗣公還令人遺之席曰：「吾聞汝今者發蓐而席弊甚，賜汝席」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛嗣君之時，有人於令之左右，縣令有發蓐而席弊甚，嗣公……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-31_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-1\",\"order\":1,\"canonicalText\":\"六微：一曰、權借在下，二曰、利異外借，三曰、託於似類，四曰、利害有反，五曰、參疑內爭，六曰、敵國廢置。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-1\",\"order\":2,\"canonicalText\":\"此六者，主之所察也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-2\",\"order\":1,\"canonicalText\":\"權勢不可以借人，上失其一，臣以為百。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-2\",\"order\":2,\"canonicalText\":\"故臣得借則力多，力多則內外為用，內外為用則人主壅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-2\",\"order\":3,\"canonicalText\":\"其說在老聃之言失魚也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-2\",\"order\":4,\"canonicalText\":\"是以人主久語，而左右鬻懷刷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-2\",\"order\":5,\"canonicalText\":\"其患在胥僮之諫厲公，與州侯之一言，而燕人浴矢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-3\",\"order\":1,\"canonicalText\":\"權借一\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":1,\"canonicalText\":\"君臣之利異，故人臣莫忠，故臣利立而主利滅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":2,\"canonicalText\":\"是以姦臣者，召敵兵以內除，舉外事以眩主，苟成其私利，不顧國患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":3,\"canonicalText\":\"其說在衛人之夫妻禱祝也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":4,\"canonicalText\":\"故戴歇議子弟，而三桓攻昭公；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":5,\"canonicalText\":\"公叔內齊軍，而翟黃召韓兵；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":6,\"canonicalText\":\"太宰嚭說大夫種，大成牛教申不害；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":7,\"canonicalText\":\"司馬喜告趙王，呂倉規秦、楚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-4_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-4\",\"order\":8,\"canonicalText\":\"宋石遺衛君書，白圭教暴譴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-5\",\"order\":1,\"canonicalText\":\"利異二\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-6\",\"order\":1,\"canonicalText\":\"似類之事，人主之所以失誅，而大臣之所以成私也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-6_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-6\",\"order\":2,\"canonicalText\":\"是以門人捐水而夷射誅，濟陽自矯而二人罪，司馬喜殺爰騫而季辛誅，鄭袖言惡臭而新人劓，費無忌教郤宛而令尹誅，陳需殺張壽而犀首走。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-6_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-6\",\"order\":3,\"canonicalText\":\"故燒芻廥而中山罪，殺老儒而濟陽賞也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-7\",\"order\":1,\"canonicalText\":\"似類三\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":1,\"canonicalText\":\"事起而有所利，其屍主之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":2,\"canonicalText\":\"有所害，必反察之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":3,\"canonicalText\":\"是以明主之論也，國害則省其利者，臣害則察其反者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":4,\"canonicalText\":\"其說在楚兵至而陳需相，黍種貴而廩吏覆。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":5,\"canonicalText\":\"是以昭奚恤執販茅，而不僖侯譙其次；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-8_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-8\",\"order\":6,\"canonicalText\":\"文公髮繞炙，而穰侯請立帝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-9\",\"order\":1,\"canonicalText\":\"有反四\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-10\",\"order\":1,\"canonicalText\":\"參疑之勢，亂之所由生也，故明主慎之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-10_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-10\",\"order\":2,\"canonicalText\":\"是以晉驪姬殺太子申生，而鄭夫人用毒藥，郤州籲殺其君完，公子根取東周，王子職甚有寵，而商臣果作亂，嚴遂、韓廆爭而哀侯果遇賊，田常、闞止、戴驩、皇喜敵而宋君、簡公殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-10_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-10\",\"order\":3,\"canonicalText\":\"其說在狐突之稱二好，與鄭昭之對未生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-11\",\"order\":1,\"canonicalText\":\"參疑五\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-12\",\"order\":1,\"canonicalText\":\"敵之所務在淫察而就靡，人主不察則敵廢置矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-12_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-12\",\"order\":2,\"canonicalText\":\"故文王資費仲，而秦王患楚使，黎且去仲尼，而乾象沮甘茂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-12_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-12\",\"order\":3,\"canonicalText\":\"是以子胥宣言而子常用，內美人而虞、虢亡，佯遺書而萇宏死，用雞猳而鄶桀盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-13\",\"order\":1,\"canonicalText\":\"廢置六\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-14\",\"order\":1,\"canonicalText\":\"參疑廢置之事，明主絕之於內而施之於外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-14_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-14\",\"order\":2,\"canonicalText\":\"資其輕者，輔其弱者，此謂廟攻。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-14_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-14\",\"order\":3,\"canonicalText\":\"參伍既用於內，觀聽又行於外，則敵偽得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-14_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-14\",\"order\":4,\"canonicalText\":\"其說在秦侏儒之告惠文君也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-14_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-14\",\"order\":5,\"canonicalText\":\"故襄疵言襲鄴，而嗣公賜令蓆。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-15_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-15\",\"order\":1,\"canonicalText\":\"廟攻\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-16_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-16\",\"order\":1,\"canonicalText\":\"右經\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-17_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-17\",\"order\":1,\"canonicalText\":\"說一\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-18_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-18\",\"order\":1,\"canonicalText\":\"勢重者，人主之淵也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-18_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-18\",\"order\":2,\"canonicalText\":\"臣者，勢重之魚也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-18_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-18\",\"order\":3,\"canonicalText\":\"魚失於淵而不可復得也，人主失其勢重於臣而不可復收也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-18_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-18\",\"order\":4,\"canonicalText\":\"古之人難正言，故託之於魚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-19_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-19\",\"order\":1,\"canonicalText\":\"賞罰者，利器也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-19_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-19\",\"order\":2,\"canonicalText\":\"君操之以制臣，臣得之以擁主。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-19_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-19\",\"order\":3,\"canonicalText\":\"故君先見所賞則臣鬻之以為德，君先見所罰則臣鬻之以為威。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-19_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-19\",\"order\":4,\"canonicalText\":\"故曰：「國之利器不可以示人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-19_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-19\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-20_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-20\",\"order\":1,\"canonicalText\":\"靖郭君相齊，與故人久語則故人富，懷左右刷則左右重。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-20_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-20\",\"order\":2,\"canonicalText\":\"久語懷刷，小資也，猶以成富，況於吏勢乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":1,\"canonicalText\":\"晉厲公之時，六卿貴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":2,\"canonicalText\":\"胥僮長魚矯諫曰：「大臣貴重，敵主爭事，外市樹黨，下亂國法，上以劫主，而國不危者，未嘗有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":3,\"canonicalText\":\"」公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":4,\"canonicalText\":\"」乃誅三卿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":5,\"canonicalText\":\"胥僮長魚矯又諫曰：「夫同罪之人偏誅而不盡，是懷怨而借之閒也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":6,\"canonicalText\":\"」公曰：「吾一朝而夷三卿，予不忍盡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":7,\"canonicalText\":\"」長魚矯對曰：「公不忍之，彼將忍公。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-21_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-21\",\"order\":8,\"canonicalText\":\"」公不聽，居三月，諸卿作難，遂殺厲公而分其地。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-22_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-22\",\"order\":1,\"canonicalText\":\"州侯相荊，貴而主斷，荊王疑之，因問左右，左右對曰「無有」，如出一口也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":1,\"canonicalText\":\"燕人無惑，故浴狗矢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":2,\"canonicalText\":\"燕人、其妻有私通於士，其夫早自外而來，士適出，夫曰：「何客也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":3,\"canonicalText\":\"」其妻曰：「無客。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":4,\"canonicalText\":\"」問左右，左右言無有，如出一口。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":5,\"canonicalText\":\"其妻曰：「公惑易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-23_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-23\",\"order\":6,\"canonicalText\":\"」因浴之以狗矢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":2,\"canonicalText\":\"燕人李季好遠出，其妻私有通於士，季突至，士在內中，妻患之，其室婦曰：「令公子裸而解髮直出門，吾屬佯不見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":3,\"canonicalText\":\"」於是公子從其計，疾走出門，季曰：「是何人也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":4,\"canonicalText\":\"」家室皆曰：「無有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":5,\"canonicalText\":\"」季曰：「吾見鬼乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":6,\"canonicalText\":\"」婦人曰：「然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":7,\"canonicalText\":\"」「為之奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":8,\"canonicalText\":\"」曰：「取五姓之矢浴之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":9,\"canonicalText\":\"」季曰：「諾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":10,\"canonicalText\":\"」乃浴以矢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-24_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-24\",\"order\":11,\"canonicalText\":\"一曰浴以蘭湯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-25_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-25\",\"order\":1,\"canonicalText\":\"說二\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-26_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-26\",\"order\":1,\"canonicalText\":\"衛人有夫妻禱者，而祝曰：「使我無故，得百束布。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-26_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-26\",\"order\":2,\"canonicalText\":\"」其夫曰：「何少也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-26_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-26\",\"order\":3,\"canonicalText\":\"」對曰：「益是，子將以買妾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-26_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-26\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-27_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-27\",\"order\":1,\"canonicalText\":\"荊王欲宦諸公子於四鄰，戴歇曰：「不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-27_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-27\",\"order\":2,\"canonicalText\":\"」「宦公子於四鄰，四鄰必重之」。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-27_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-27\",\"order\":3,\"canonicalText\":\"曰：「子出者重，重則必為所重之國黨，則是教子於外市也，不便。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-27_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-27\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":1,\"canonicalText\":\"魯孟孫、叔孫、季孫相戮力劫昭公，遂奪其國而擅其制。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":2,\"canonicalText\":\"魯三桓公偪，昭公攻季孫氏，而孟孫氏、叔孫氏相與謀曰：「救之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":3,\"canonicalText\":\"」叔孫氏之御者曰：「我，家臣也，安知公家？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":4,\"canonicalText\":\"凡有季孫與無季孫於我孰利？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":5,\"canonicalText\":\"」皆曰：「無季孫必無叔孫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":6,\"canonicalText\":\"」「然則救之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-28_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-28\",\"order\":7,\"canonicalText\":\"」於是撞西北隅而入，孟孫見叔孫之旗入，亦救之，三桓為一，昭公不勝，逐之死於乾侯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-29_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-29\",\"order\":1,\"canonicalText\":\"公叔相韓而有攻齊，公仲甚重於王，公叔恐王之相公仲也，使齊、韓約而攻魏，公叔因內齊軍於鄭，以劫其君，以固其位，而信兩國之約。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-30_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-30\",\"order\":1,\"canonicalText\":\"翟璜，魏王之臣也，而善於韓，乃召韓兵令之攻魏，因請為魏王搆之以自重也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":1,\"canonicalText\":\"越王攻吳，王吳王謝而告服，越王欲許之，范蠡、大夫種曰：「不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":2,\"canonicalText\":\"昔天以越與吳，吳不受，今天反夫差，亦天禍也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":3,\"canonicalText\":\"以吳予越，再拜受之，不可許也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":4,\"canonicalText\":\"」太宰嚭遺大夫種書曰：「狡兔盡則良犬烹，敵國滅則謀臣亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":5,\"canonicalText\":\"大夫何不釋吳而患越乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":6,\"canonicalText\":\"」大夫種受書讀之，太息而歎曰：「殺之，越與吳同命。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-31_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-31\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-32_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-32\",\"order\":1,\"canonicalText\":\"大成牛從趙謂申不害於韓曰：「以韓重我於趙，請以趙重子於韓，是子有兩韓，我有兩趙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-32_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-32\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-33_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-33\",\"order\":1,\"canonicalText\":\"司馬喜，中山君之臣也，而善於趙，嘗以中山之謀微告趙王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-34_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-34\",\"order\":1,\"canonicalText\":\"呂倉，魏王之臣也，而善於秦、荊，微諷秦、荊令之攻魏，因請行和以自重也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-35_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-35\",\"order\":1,\"canonicalText\":\"宋石，魏將也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-35_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-35\",\"order\":2,\"canonicalText\":\"衛君，荊將也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-35_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-35\",\"order\":3,\"canonicalText\":\"兩國搆難，二子皆將，宋石遺衛君書曰：「二軍相當，兩旗相望，唯毋一戰，戰必不兩存，此乃兩主之事也，與子無有私怨，善者相避也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-35_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-35\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-36_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-36\",\"order\":1,\"canonicalText\":\"白圭相魏，暴譴相韓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-36_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-36\",\"order\":2,\"canonicalText\":\"白圭謂暴譴曰：「子以韓輔我於魏，我請以魏待子於韓，臣長用魏，子長用韓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-36_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-36\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-37_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-37\",\"order\":1,\"canonicalText\":\"說三\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":1,\"canonicalText\":\"齊中大夫有夷射者，御飲於王，醉甚而出，倚於郎門，門者刖跪請曰：「足下無意賜之餘瀝乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":2,\"canonicalText\":\"」夷射曰：「叱去！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":3,\"canonicalText\":\"刑餘之人，何事乃敢乞飲長者？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":4,\"canonicalText\":\"」刖跪走退，及夷射去，刖跪因捐水郎門霤下，類溺者之狀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":5,\"canonicalText\":\"明日，王出而訶之曰：「誰溺於是？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":6,\"canonicalText\":\"」刖跪對曰：「臣不見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":7,\"canonicalText\":\"雖然，昨日中大夫夷射立於此。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-38_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-38\",\"order\":8,\"canonicalText\":\"」王因誅夷射而殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-39_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-39\",\"order\":1,\"canonicalText\":\"魏王臣二人不善濟陽君，濟陽君因偽令人矯王命而謀攻己，王使人問濟陽君曰：「誰與恨？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-39_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-39\",\"order\":2,\"canonicalText\":\"」對曰：「無敢與恨，雖然，嘗與二人不善，不足以至於此。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-39_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-39\",\"order\":3,\"canonicalText\":\"」王問左右，左右曰：「固然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-39_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-39\",\"order\":4,\"canonicalText\":\"」王因誅二人者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-40_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-40\",\"order\":1,\"canonicalText\":\"季辛與爰騫相怨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-40_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-40\",\"order\":2,\"canonicalText\":\"司馬喜新與季辛惡，因微令人殺爰騫，中山之君以為季辛也，因誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":1,\"canonicalText\":\"荊王所愛妾有鄭袖者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":2,\"canonicalText\":\"荊王新得美女，鄭袖因教之曰：「王甚喜人之掩口也，為近王，必掩口。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":3,\"canonicalText\":\"」美女入見，近王，因掩口，王問其故，鄭袖曰：「此固言惡王之臭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":4,\"canonicalText\":\"」及王與鄭袖、美女三人坐，袖因先誡御者曰：「王適有言，必亟聽從。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":5,\"canonicalText\":\"」王言美女前，近王，甚數掩口，王悖然怒曰：「劓之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-41_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-41\",\"order\":6,\"canonicalText\":\"」御因揄刀而劓美人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":2,\"canonicalText\":\"魏王遺荊王美人，荊王甚悅之，夫人鄭袖知王悅愛之也，亦悅愛之，甚於王，衣服玩好擇其所欲為之，王曰：「夫人知我愛新人也，其悅愛之甚於寡人，此孝子所以養親，忠臣之所以事君也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":3,\"canonicalText\":\"」夫人知王之不以己為妒也，因為新人曰：「王甚悅愛子，然惡子之鼻，子見王，常掩鼻，則王長幸子矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":4,\"canonicalText\":\"」於是新人從之，每見王，常掩鼻，王謂夫人曰：「新人見寡人常掩鼻何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":5,\"canonicalText\":\"」對曰：「不己知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":6,\"canonicalText\":\"」王強問之，對曰：「頃嘗言惡聞王臭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":7,\"canonicalText\":\"」王怒曰：「劓之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":8,\"canonicalText\":\"」夫人先誡御者曰：「王適有言，必可從命。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-42_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-42\",\"order\":9,\"canonicalText\":\"」御者因揄刀而劓美人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":1,\"canonicalText\":\"費無極，荊令尹之近者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":2,\"canonicalText\":\"郤宛新事令尹，令尹甚愛之，無極因謂令尹曰：「君愛宛甚，何不一為酒其家？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":3,\"canonicalText\":\"」令尹曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":4,\"canonicalText\":\"」因令之為具於郤宛之家。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":5,\"canonicalText\":\"無極教宛曰：「令尹甚傲而好兵，子必謹敬，先亟陳兵堂下及門庭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":6,\"canonicalText\":\"」宛因為之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":7,\"canonicalText\":\"令尹往而大驚曰：「此何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":8,\"canonicalText\":\"」無極曰：「君殆去之，事未可知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-43_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-43\",\"order\":9,\"canonicalText\":\"」令尹大怒，舉兵而誅郤宛，遂殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-44_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-44\",\"order\":1,\"canonicalText\":\"犀首與張壽為怨，陳需新入，不善犀首，因使人微殺張壽，魏王以為犀首也，乃誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-45_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-45\",\"order\":1,\"canonicalText\":\"中山有賤公子，馬甚瘦，車甚弊，左右有私不善者，乃為之請王曰：「公子甚貧，馬甚瘦，王何不益之馬食？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-45_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-45\",\"order\":2,\"canonicalText\":\"」王不許，左右因微令夜燒芻廄，王以為賤公子也，乃誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-46_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-46\",\"order\":1,\"canonicalText\":\"魏有老儒而不善濟陽君，客有與老儒私怨者，因攻老儒殺之以德於濟陽君曰：「臣為其不善君也，故為君殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-46_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-46\",\"order\":2,\"canonicalText\":\"」濟陽君因不察而賞之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-47_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-47\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-47_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-47\",\"order\":2,\"canonicalText\":\"濟陽君有少庶子，有不見知，欲入愛於君者，齊使老儒掘藥於馬梨之山，濟陽少庶子欲以為功，入見於君曰：「齊使老儒掘藥於馬梨之山，名掘藥也，實閒君之國，君殺之，是將以濟陽君抵罪於齊矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-47_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-47\",\"order\":3,\"canonicalText\":\"臣請刺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-47_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-47\",\"order\":4,\"canonicalText\":\"」君曰：「可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-47_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-47\",\"order\":5,\"canonicalText\":\"」於是明日得之城陰而刺之，濟陽君還益親之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-48_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-48\",\"order\":1,\"canonicalText\":\"說四\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-49_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-49\",\"order\":1,\"canonicalText\":\"陳需，魏王之臣也，善於荊王，而令荊攻魏，荊攻魏，陳需因請為魏王行解之，因以荊勢相魏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-50_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-50\",\"order\":1,\"canonicalText\":\"韓昭侯之時，黍種嘗貴甚，昭侯令人覆廩，吏果竊黍種而糶之甚多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-51_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-51\",\"order\":1,\"canonicalText\":\"昭奚恤之用荊也，有燒倉廥窌者，而不知其人，昭奚恤令吏執販茅者而問之，果燒也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-52_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-52\",\"order\":1,\"canonicalText\":\"昭僖侯之時，宰人上食而羹中有生肝焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-52_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-52\",\"order\":2,\"canonicalText\":\"昭侯召宰人之次而誚之曰：「若何為置生肝寡人羹中？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-52_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-52\",\"order\":3,\"canonicalText\":\"」宰人頓首服死罪曰：「竊欲去尚宰人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-52_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-52\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":2,\"canonicalText\":\"僖侯浴，湯中有礫，僖侯曰：「尚浴免則有當代者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":3,\"canonicalText\":\"」左右對曰：「有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":4,\"canonicalText\":\"」僖侯曰：「召而來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":5,\"canonicalText\":\"」譙之曰：「何為置礫湯中？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":6,\"canonicalText\":\"」對曰：「尚浴免，則臣得代之，是以置礫湯中。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-53_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-53\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":1,\"canonicalText\":\"文公之時，宰臣上炙而髮繞之，文公召宰人而譙之曰：「女欲寡人之哽邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":2,\"canonicalText\":\"奚為以髮繞炙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":3,\"canonicalText\":\"」宰人頓首再拜請曰：「臣有死罪三：援礪砥刀，利猶幹將也，切肉，肉斷而髮不斷，臣之罪一也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":4,\"canonicalText\":\"援木而貫臠而不見髮，臣之罪二也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":5,\"canonicalText\":\"奉熾爐，炭火盡赤紅，而炙熟而髮不燒，臣之罪三也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":6,\"canonicalText\":\"堂下得無微有疾臣者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":7,\"canonicalText\":\"」公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-54_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-54\",\"order\":8,\"canonicalText\":\"」乃召其堂下而譙之，果然，乃誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":2,\"canonicalText\":\"晉平公觴客，少庶子進炙而髮繞之，平公趣殺炮人，毋有反令，炮人呼天曰：「嗟乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":3,\"canonicalText\":\"臣有三罪，死而不自知乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":4,\"canonicalText\":\"」平公曰：「何謂也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":5,\"canonicalText\":\"」對曰：「臣刀之利，風靡骨斷而髮不斷，是臣之一死也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":6,\"canonicalText\":\"桑炭炙之，肉紅白而髮不焦，是臣之二死也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":7,\"canonicalText\":\"炙熟又重睫而視之，髮繞炙而目不見，是臣之三死也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":8,\"canonicalText\":\"意者堂下其有翳憎臣者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":9,\"canonicalText\":\"殺臣不亦蚤乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-55_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-55\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-56_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-56\",\"order\":1,\"canonicalText\":\"穰侯相秦而齊強，穰侯欲立秦為帝而齊不聽，因請立齊為東帝而不能成也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-57_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-57\",\"order\":1,\"canonicalText\":\"說五\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-58_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-58\",\"order\":1,\"canonicalText\":\"晉獻公之時，驪姬貴，擬於後妻，而欲以其子奚齊代太子申生，因患申生於君而殺之，遂立奚齊為太子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-59_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-59\",\"order\":1,\"canonicalText\":\"鄭君已立太子矣，而有所愛美女欲以其子為後，夫人恐，因用毒藥賊君殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-60_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-60\",\"order\":1,\"canonicalText\":\"衛州籲重於衛，擬於君，群臣百姓盡畏其勢重，州籲果殺其君而奪之政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-61_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-61\",\"order\":1,\"canonicalText\":\"公子朝，周太子也，弟公子根甚有寵於君，君死，遂以東周叛，分為兩國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-62_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-62\",\"order\":1,\"canonicalText\":\"楚成王以商臣為太子，既而又欲置公子職。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-62_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-62\",\"order\":2,\"canonicalText\":\"商臣作亂，遂攻殺成王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":2,\"canonicalText\":\"楚成王商臣為太子，既欲置公子職。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":3,\"canonicalText\":\"商臣聞之，未察也，乃為其傅潘崇曰：「奈何察之也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":4,\"canonicalText\":\"」潘崇曰：「饗江芊而勿敬也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":5,\"canonicalText\":\"」太子聽之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":6,\"canonicalText\":\"江芊曰：「呼役夫！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":7,\"canonicalText\":\"宜君王之慾廢女而立職也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":8,\"canonicalText\":\"」商臣曰：「信矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":9,\"canonicalText\":\"」潘崇曰：「能事之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":10,\"canonicalText\":\"」曰：「不能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":11,\"canonicalText\":\"」「能為之諸侯乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":12,\"canonicalText\":\"」曰：「不能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":13,\"canonicalText\":\"」「能舉大事乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":14,\"canonicalText\":\"」曰：「能。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-63_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-63\",\"order\":15,\"canonicalText\":\"」於是乃起宿營之甲而攻成王，成王請食能膰而死，不許，遂自殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-64_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-64\",\"order\":1,\"canonicalText\":\"韓廆相韓哀侯，嚴遂重於君，二人甚相害也，嚴遂乃令人刺韓廆於朝，韓廆走君而抱之，遂刺韓廆而兼哀侯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-65_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-65\",\"order\":1,\"canonicalText\":\"田恆相齊，闞止重於簡公，二人相憎而欲相賊也，田恆因行私惠以取其國，遂殺簡公而奪之政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-66_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-66\",\"order\":1,\"canonicalText\":\"戴驩為宋太宰，皇喜重於君，二人爭事而相害也，皇喜遂殺宋君而奪其政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-67_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-67\",\"order\":1,\"canonicalText\":\"狐突曰：「國君好內則太子危，好外則相室危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-67_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-67\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-68_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-68\",\"order\":1,\"canonicalText\":\"鄭君問鄭昭曰：「太子亦何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-68_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-68\",\"order\":2,\"canonicalText\":\"」對曰：「太子未生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-68_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-68\",\"order\":3,\"canonicalText\":\"」君曰：「太子已置而曰未生何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-68_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-68\",\"order\":4,\"canonicalText\":\"」對曰：「太子雖置，然而君之好色不已，所愛有子，君必愛之，愛之則必欲以為後，臣故曰太子未生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-68_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-68\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-69_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-69\",\"order\":1,\"canonicalText\":\"說六\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-70_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-70\",\"order\":1,\"canonicalText\":\"文王資費仲而遊於紂之旁，令之諫紂而亂其心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":1,\"canonicalText\":\"荊王使人之秦，秦王甚禮之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":2,\"canonicalText\":\"王曰：「敵國有賢者，國之憂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":3,\"canonicalText\":\"今荊王之使者甚賢，寡人患之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":4,\"canonicalText\":\"」群臣諫曰：「以王之賢聖與國之資厚，願荊王之賢人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":5,\"canonicalText\":\"王何不深知之而陰有之，荊以為外用也，則必誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-71_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-71\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-72_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-72\",\"order\":1,\"canonicalText\":\"仲尼為政於魯，道不拾遺，齊景公患之，梨且謂景公曰：「去仲尼猶吹毛耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-72_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-72\",\"order\":2,\"canonicalText\":\"君何不迎之以重祿高位，遺哀公女樂以驕榮其意。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-72_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-72\",\"order\":3,\"canonicalText\":\"哀公新樂之，必怠於政，仲尼必諫，諫必輕絕於魯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-72_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-72\",\"order\":4,\"canonicalText\":\"」景公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-72_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-72\",\"order\":5,\"canonicalText\":\"」乃令梨且以女樂二八遺哀公，哀公樂之，果怠於政，仲尼諫，不聽，去而之楚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":1,\"canonicalText\":\"楚王謂乾象曰：「吾欲以楚扶甘茂而相之秦可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":2,\"canonicalText\":\"」乾象對曰：「不可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":3,\"canonicalText\":\"」王曰：「何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":4,\"canonicalText\":\"」曰：「甘茂少而事史舉先生，史舉，上蔡之監門也，大不事君，小不事家，以苛刻聞天下，茂事之順焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":5,\"canonicalText\":\"惠王之明，張儀之辨也，茂事之，取十官而免於罪，是茂賢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":6,\"canonicalText\":\"」王曰：「相人敵國而相賢，其不可何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":7,\"canonicalText\":\"」乾象曰：「前時王使邵滑之越，五年而能亡越，所以然者，越亂而楚治也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":8,\"canonicalText\":\"日者知用之越，今亡之秦，不亦太亟忘乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":9,\"canonicalText\":\"」王曰：「然則為之奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":10,\"canonicalText\":\"」乾象對曰：「不如相共立。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":11,\"canonicalText\":\"」王曰：「共立可相何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":12,\"canonicalText\":\"」對曰：「共立少見愛幸，長為貴卿，被王衣，含杜若，握玉環，以聽於朝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":13,\"canonicalText\":\"且利以亂秦矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-73_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-73\",\"order\":14,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-74_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-74\",\"order\":1,\"canonicalText\":\"吳政荊，子胥使人宣言於荊曰：「子期用，將擊之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-74_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-74\",\"order\":2,\"canonicalText\":\"子常用，將去之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-74_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-74\",\"order\":3,\"canonicalText\":\"」荊人聞之，因用子常而退子期也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-74_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-74\",\"order\":4,\"canonicalText\":\"吳人擊之，遂勝之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-75_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-75\",\"order\":1,\"canonicalText\":\"晉獻公伐虞、虢，乃遺之屈產之乘，垂棘之璧，女樂二八，以榮其意而亂其政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-76_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-76\",\"order\":1,\"canonicalText\":\"叔向之讒萇弘也，為書曰：「萇弘謂叔向曰：子為我謂晉君，所與君期者時可矣，何不亟以兵來？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-76_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-76\",\"order\":2,\"canonicalText\":\"」因佯遺其書周君之庭而急去行，周以萇弘為賣周也，乃誅萇弘而殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-77_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-77\",\"order\":1,\"canonicalText\":\"鄭桓公將欲襲鄶，先問鄶之豪傑良臣辯智果敢之士，盡與其姓名，擇鄶之良田賂之，為官爵之名而書之，因為設壇場郭門之外而埋之，釁之以雞豭，若盟狀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-77_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-77\",\"order\":2,\"canonicalText\":\"鄶君以為內難也而盡殺其良臣，桓公襲鄶，遂取之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-78_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-78\",\"order\":1,\"canonicalText\":\"說七\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-79_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-79\",\"order\":1,\"canonicalText\":\"七秦侏儒善於荊王，而陰有善荊王左右而內重於惠文君，荊適有謀，侏儒常先聞之以告惠文君。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-80_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-80\",\"order\":1,\"canonicalText\":\"鄴令襄疵，陰善趙王左右，趙王謀襲鄴，襄疵常輒聞而先言之魏王，魏王備之，趙乃輒還。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-81_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-81\",\"order\":1,\"canonicalText\":\"衛嗣君之時，有人於令之左右，縣令有發蓐而席弊甚，嗣公還令人遺之席曰：「吾聞汝今者發蓐而席弊甚，賜汝席。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-31_p-81_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-31\",\"passageId\":\"han-fei-zi_ch-31_p-81\",\"order\":2,\"canonicalText\":\"」縣令大驚，以君為神也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
